import java.util.Scanner;
public class JThreeBoolean3 {
	public static void main(String[] args) {
		//Khatwa 1: Qra madkhulat al-mustakhdim
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil qimat al-mutaghayyir al-buliyani al-awwal (true aw false):");
		boolean a = scan.nextBoolean();		
		System.out.println("Adkhil qimat al-mutaghayyir al-buliyani al-thani (true aw false):");
		boolean b = scan.nextBoolean();	
		System.out.println("Adkhil qimat al-mutaghayyir al-buliyani al-thalith (true aw false):");
		boolean c = scan.nextBoolean();		
		scan.close();
		//Khatwa 2: Ktib al-ta3bir al-buliyani litaqarir law kanat al-thalatha mutasawiyat
		boolean value = (a == b && b == c);
		System.out.println(value);
	}
}
